import Foundation
import AppKit
import CoreGraphics
import Carbon
import ApplicationServices

/// macOS uygulamalarına pano ve sentetik klavye olayı üzerinden metin gönderen yönetici.
/// Hedef uygulamanın kendi metin alanı ve güvenlik politikası, gerçek yapıştırma
/// davranışını etkiler. Okunabilir alanlarda gönderilen metin ayrıca doğrulanır.
///
/// Pano Koruması:
/// - nspasteboard.org topluluk standardı `org.nspasteboard.TransientType` ve
///   `org.nspasteboard.AutoGeneratedType` bayrakları eklenerek Raycast, Maccy, Alfred
///   gibi pano yöneticilerinin geçmişe kaydetmesi önlenir.
/// - Eski pano yalnızca metnin hedefte bulunduğu doğrulandıktan sonra geri yüklenir.
public class TextInjector {
    public static let shared = TextInjector()

    private let queue = DispatchQueue(label: "com.voicetyping.textinjector", qos: .userInteractive)

    // nspasteboard.org topluluk standardı geçici pano tipleri (Raycast, Maccy, Alfred vb. için)
    public static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    public static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    static func transientClipboardItem(text: String) -> NSPasteboardItem? {
        let item = NSPasteboardItem()
        guard item.setString(text, forType: .string) else { return nil }
        item.setData(Data(), forType: transientType)
        item.setData(Data(), forType: autoGeneratedType)
        return item
    }

    private let cancellationLock = NSLock()
    private var cancellationGeneration: UInt64 = 0
    private let clipboardEnvironmentOverride: ((String) -> ClipboardPasteTransaction.Environment)?
    private let targetCheckOverride: ((TargetContext?) -> TargetInputManager.TargetCheck)?
    private let selectedTextEnvironmentOverride: ((TargetContext) -> SelectedTextTransaction.Environment)?
    private let restoreTargetOverride: ((TargetContext) -> Bool)?
    private let fallbackClipboardOverride: ((String) -> Bool)?
    private let configProvider: () -> AppConfig

    init(
        clipboardEnvironment: ((String) -> ClipboardPasteTransaction.Environment)? = nil,
        targetCheck: ((TargetContext?) -> TargetInputManager.TargetCheck)? = nil,
        selectedTextEnvironment: ((TargetContext) -> SelectedTextTransaction.Environment)? = nil,
        restoreTarget: ((TargetContext) -> Bool)? = nil,
        fallbackClipboard: ((String) -> Bool)? = nil,
        configProvider: @escaping () -> AppConfig = { ConfigManager.shared.config }
    ) {
        clipboardEnvironmentOverride = clipboardEnvironment
        targetCheckOverride = targetCheck
        selectedTextEnvironmentOverride = selectedTextEnvironment
        restoreTargetOverride = restoreTarget
        fallbackClipboardOverride = fallbackClipboard
        self.configProvider = configProvider
    }

    private func checkTarget(_ target: TargetContext?) -> TargetInputManager.TargetCheck {
        if let targetCheckOverride { return targetCheckOverride(target) }
        guard let target else { return .changed(reason: "Hedef alan bulunamadı") }
        return TargetInputManager.shared.verify(target)
    }

    public func cancelPendingInjections() {
        cancellationLock.lock()
        cancellationGeneration &+= 1
        cancellationLock.unlock()
    }

    private func currentGeneration() -> UInt64 {
        cancellationLock.lock()
        defer { cancellationLock.unlock() }
        return cancellationGeneration
    }

    private static func onMain<T>(_ work: () -> T) -> T {
        Thread.isMainThread ? work() : DispatchQueue.main.sync(execute: work)
    }

    public func getClipboard() -> String {
        return NSPasteboard.general.string(forType: .string) ?? ""
    }

    @discardableResult
    public func setClipboard(_ text: String) -> Bool {
        let pb = NSPasteboard.general
        pb.clearContents()
        return pb.setString(text, forType: .string)
    }

    /// Panodaki okunabilen öğe ve formatları kopyalar.
    public func captureClipboardSnapshot() -> [NSPasteboardItem] {
        let pb = NSPasteboard.general
        guard let items = pb.pasteboardItems, !items.isEmpty else { return [] }

        var snapshot: [NSPasteboardItem] = []
        for item in items {
            let copy = NSPasteboardItem()
            for type in item.types {
                if let data = item.data(forType: type) {
                    copy.setData(data, forType: type)
                }
            }
            snapshot.append(copy)
        }
        return snapshot
    }

    /// Refuse a destructive clipboard operation if any advertised format cannot
    /// be copied. A partial snapshot would silently discard the missing data.
    static func copyCompleteClipboardItems(
        _ items: [NSPasteboardItem],
        readData: (NSPasteboardItem, NSPasteboard.PasteboardType) -> Data? = { $0.data(forType: $1) }
    ) -> [NSPasteboardItem]? {
        var snapshot: [NSPasteboardItem] = []
        for item in items {
            guard !item.types.isEmpty else { return nil }
            let copy = NSPasteboardItem()
            for type in item.types {
                guard let data = readData(item, type), copy.setData(data, forType: type) else { return nil }
            }
            snapshot.append(copy)
        }
        return snapshot
    }

    func captureCompleteClipboardSnapshot(from pasteboard: NSPasteboard = .general) -> [NSPasteboardItem]? {
        let initialCount = pasteboard.changeCount
        let items: [NSPasteboardItem]
        if let existingItems = pasteboard.pasteboardItems {
            items = existingItems
        } else {
            guard pasteboard.types?.isEmpty ?? true else { return nil }
            items = []
        }
        guard let snapshot = Self.copyCompleteClipboardItems(items),
              pasteboard.changeCount == initialCount else { return nil }
        return snapshot
    }

    /// Alınan tam sadakatli panoyu NSPasteboard.general'a geri yükler.
    /// Boş bir snapshot da geçerli bir durumdur: kullanıcının panosu boşsa
    /// dikte metni bırakılmamalı, işlem sonunda pano yeniden boşaltılmalıdır.
    @discardableResult
    public func restoreClipboardSnapshot(_ snapshot: [NSPasteboardItem]) -> Bool {
        let pb = NSPasteboard.general
        pb.clearContents()
        guard !snapshot.isEmpty else { return true }
        return pb.writeObjects(snapshot)
    }

    /// Aktif (ASCII yazabilen) klavye düzeninde "v" karakterini üreten fiziksel tuş.
    /// Sanal tuş kodu fiziksel konumdur: Türkçe-F düzeninde ANSI V konumu "c"
    /// yazar, dolayısıyla sabit 0x09 kodu Cmd+V yerine Cmd+C gönderir. Dvorak ve
    /// benzeri düzenler de aynı sorundan etkilenir. TIS API'leri ana thread ister.
    public static func keyCodeForCharacter(_ character: String, fallback: CGKeyCode) -> CGKeyCode {
        resolvedKeyCodeForCharacter(character) ?? fallback
    }

    static func resolvedKeyCodeForCharacter(_ character: String) -> CGKeyCode? {
        guard let source = TISCopyCurrentASCIICapableKeyboardLayoutInputSource()?.takeRetainedValue(),
              let layoutPtr = TISGetInputSourceProperty(source, kTISPropertyUnicodeKeyLayoutData) else {
            return nil
        }
        let layoutData = Unmanaged<CFData>.fromOpaque(layoutPtr).takeUnretainedValue() as Data
        let target = character.lowercased()

        return layoutData.withUnsafeBytes { raw -> CGKeyCode? in
            guard let layout = raw.baseAddress?.assumingMemoryBound(to: UCKeyboardLayout.self) else { return nil }
            for keyCode in 0..<128 {
                var deadKeyState: UInt32 = 0
                var chars = [UniChar](repeating: 0, count: 4)
                var length = 0
                let status = UCKeyTranslate(
                    layout,
                    UInt16(keyCode),
                    UInt16(kUCKeyActionDown),
                    0,
                    UInt32(LMGetKbdType()),
                    OptionBits(kUCKeyTranslateNoDeadKeysBit),
                    &deadKeyState,
                    chars.count,
                    &length,
                    &chars
                )
                if status == noErr, length > 0,
                   String(utf16CodeUnits: chars, count: length) == target {
                    return CGKeyCode(keyCode)
                }
            }
            return nil
        }
    }

    /// Cmd+V olayını mümkünse yalnızca doğrulanan hedef sürece gönderir.
    @discardableResult
    public func simulateCmdV(vKeyCode: CGKeyCode = 0x09, targetPID: pid_t? = nil) -> Bool {
        let source = CGEventSource(stateID: .combinedSessionState)

        guard let eventDown = CGEvent(keyboardEventSource: source, virtualKey: vKeyCode, keyDown: true),
              let eventUp = CGEvent(keyboardEventSource: source, virtualKey: vKeyCode, keyDown: false) else {
            return false
        }

        eventDown.flags = .maskCommand
        eventUp.flags = .maskCommand
        Self.postKeyboardEvent(eventDown, targetPID: targetPID)
        Thread.sleep(forTimeInterval: 0.025)
        Self.postKeyboardEvent(eventUp, targetPID: targetPID)
        return true
    }

    private static func postKeyboardEvent(_ event: CGEvent, targetPID: pid_t?) {
        if let targetPID {
            event.postToPid(targetPID)
        } else {
            let tap: CGEventTapLocation = AXIsProcessTrusted() ? .cghidEventTap : .cgSessionEventTap
            event.post(tap: tap)
        }
    }

    /// Belirtilen sanal tuş kodunu ve tuş bayraklarını simüle eder (örn: Return, Tab, Cmd+Return)
    public func simulateKeyPress(virtualKey: CGKeyCode, flags: CGEventFlags = [], targetPID: pid_t? = nil) {
        let source = CGEventSource(stateID: .combinedSessionState)
        guard let eventDown = CGEvent(keyboardEventSource: source, virtualKey: virtualKey, keyDown: true),
              let eventUp = CGEvent(keyboardEventSource: source, virtualKey: virtualKey, keyDown: false) else {
            return
        }

        if !flags.isEmpty {
            eventDown.flags = flags
            eventUp.flags = flags
        }

        Self.postKeyboardEvent(eventDown, targetPID: targetPID)
        Thread.sleep(forTimeInterval: 0.020)
        Self.postKeyboardEvent(eventUp, targetPID: targetPID)
    }

    /// Otomatik gönderim (Auto-Submit) için istenen tuşu tetikler
    public func triggerAutoSubmit(key: String, targetPID: pid_t? = nil) {
        let k = key.lowercased().trimmingCharacters(in: .whitespaces)
        switch k {
        case "cmd_return", "cmd+return", "command_return":
            simulateKeyPress(virtualKey: 36, flags: .maskCommand, targetPID: targetPID)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Cmd + Return (⌘⏎)")
        case "shift_return", "shift+return":
            simulateKeyPress(virtualKey: 36, flags: .maskShift, targetPID: targetPID)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Shift + Return (⇧⏎)")
        case "tab":
            simulateKeyPress(virtualKey: 48, flags: [], targetPID: targetPID)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Tab (⇥)")
        default: // "return", "enter"
            simulateKeyPress(virtualKey: 36, flags: [], targetPID: targetPID)
            print("[TextInjector] ⚡ Auto-Submit tetiklendi: Return (⏎)")
        }
    }

    /// Cancels one delivery without affecting earlier deliveries still checking the clipboard.
    public final class InjectionCancellation {
        private let lock = NSLock()
        private var cancelled = false

        public init() {}

        public func cancel() {
            lock.lock()
            cancelled = true
            lock.unlock()
        }

        fileprivate var isCancelled: Bool {
            lock.lock()
            defer { lock.unlock() }
            return cancelled
        }
    }

    /// Aktarım isteğinin gönderilmesini izler; bu olay teslim kanıtı değildir.
    public struct DeliveryObserver {
        let onAttempted: () -> Void

        public init(onAttempted: @escaping () -> Void) {
            self.onAttempted = onAttempted
        }
    }

    /// Yapıştırmanın gerçek sonucu. `sent` true dönse bile metin hedefe
    /// girmemiş olabilir; kesin sonuç bu değerle bildirilir.
    public enum InjectionOutcome: Equatable {
        /// Beklenen metnin hedef alana eklendiği doğrulandı.
        case verified
        /// Metin gönderildi ama hedefteki değişiklik doğrulanamadı.
        case unverifiable
        /// Aktarım doğrulanamadı ve başka bir işlem panoyu değiştirdi.
        case unverifiableClipboardChanged
        /// Alan okunabiliyor fakat beklenen metin değişikliği görülmedi.
        case notInserted
        /// Kayıt sırasında sekme/uygulama değişti; yanlış yere yapıştırılmadı. Metin panoda.
        case targetChanged(reason: String)
        /// Pano veya klavye işlemi başarısız; metnin panoda olduğu varsayılamaz.
        case failed(reason: String)
        case cancelled
    }

    /// Odaktaki alanın karşılaştırılabilir içerik izi.
    struct FieldSnapshot: Equatable {
        let value: String?
        let count: Int?
        var selection: NSRange? = nil
        var isReadable: Bool { value != nil || count != nil || selection != nil }
    }

    static func snapshot(of element: AXUIElement?) -> FieldSnapshot {
        guard let element else { return FieldSnapshot(value: nil, count: nil) }
        var valueRef: CFTypeRef?
        var value: String?
        if AXUIElementCopyAttributeValue(element, kAXValueAttribute as CFString, &valueRef) == .success {
            value = valueRef as? String
        }
        var countRef: CFTypeRef?
        var count: Int?
        if AXUIElementCopyAttributeValue(element, kAXNumberOfCharactersAttribute as CFString, &countRef) == .success {
            count = (countRef as? NSNumber)?.intValue
        }
        var selection: NSRange?
        var selectionRef: CFTypeRef?
        if AXUIElementCopyAttributeValue(element, kAXSelectedTextRangeAttribute as CFString, &selectionRef) == .success,
           let selectionRef, CFGetTypeID(selectionRef) == AXValueGetTypeID() {
            var range = CFRange()
            if AXValueGetValue(selectionRef as! AXValue, .cfRange, &range), range.location >= 0, range.length >= 0 {
                selection = NSRange(location: range.location, length: range.length)
            }
        }
        let completeValue = completeSnapshotValue(value, count: count) { range in
            readText(in: range, from: element)
        }
        return FieldSnapshot(value: completeValue, count: count, selection: selection)
    }

    /// Some accessible editors expose the text by range instead of AXValue.
    /// Keep partial or inconsistent values unverified, and bound the extra read.
    static func completeSnapshotValue(
        _ value: String?, count: Int?, readRange: (NSRange) -> String?
    ) -> String? {
        guard let count, count >= 0, count <= 10_000 else { return value }
        if let value, value.utf16.count == count { return value }
        if count == 0 { return value == nil ? "" : value }
        guard let complete = readRange(NSRange(location: 0, length: count)),
              complete.utf16.count == count else { return value }
        return complete
    }

    static func outcome(
        before: FieldSnapshot, after: FieldSnapshot, insertedText: String,
        readRange: (NSRange) -> String? = { _ in nil }
    ) -> InjectionOutcome {
        guard before.isReadable, after.isReadable else { return .unverifiable }
        guard !insertedText.isEmpty else { return .notInserted }
        var result: InjectionOutcome = .unverifiable
        if let old = before.value, let new = after.value,
           (before.count == nil || before.count == old.utf16.count),
           (after.count == nil || after.count == new.utf16.count) {
            let normalizedOld = normalizeLineEndings(old)
            let normalizedNew = normalizeLineEndings(new)
            if let range = before.selection, range.location >= 0, range.length >= 0,
               range.location <= (old as NSString).length,
               range.length <= (old as NSString).length - range.location {
                let expected = (old as NSString).replacingCharacters(in: range, with: insertedText)
                if normalizedNew == normalizeLineEndings(expected) {
                    return normalizedNew == normalizedOld ? .unverifiable : .verified
                }
            } else if before.selection == nil,
                      matchesInsertion(old: normalizedOld, new: normalizedNew,
                                       text: normalizeLineEndings(insertedText)) {
                return .verified
            }
            let caretChanged = before.selection != nil && after.selection != nil && before.selection != after.selection
            result = normalizedOld == normalizedNew && !caretChanged ? .notInserted : .unverifiable
        } else if let a = before.count, let b = after.count, a == b,
                  let selection = before.selection, selection.length != insertedText.utf16.count {
            result = .notInserted
        }

        if let range = verificationRange(before: before, after: after, text: insertedText),
           let observed = readRange(range),
           normalizeLineEndings(observed) == normalizeLineEndings(insertedText) {
            return .verified
        }
        return result
    }

    private static func normalizeLineEndings(_ text: String) -> String {
        text.replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
    }

    /// A range read only proves insertion when the caret or character count also
    /// changed as expected. Finding matching text in the old document is not enough.
    private static func verificationRange(before: FieldSnapshot, after: FieldSnapshot, text: String) -> NSRange? {
        guard let selection = before.selection, selection.location >= 0, selection.length >= 0,
              selection.location <= Int.max - selection.length else { return nil }
        let length = text.utf16.count
        guard length > 0 else { return nil }
        let maximumLength = length <= (Int.max - 2) / 2 ? length * 2 + 2 : Int.max
        var observedLength = length
        if let caret = after.selection, caret.length == 0, caret.location > selection.location {
            let distance = caret.location - selection.location
            if distance <= maximumLength { observedLength = distance }
        }
        guard selection.location <= Int.max - observedLength else { return nil }
        let end = selection.location + observedLength
        let cursorMoved = after.selection.map { $0.length == 0 && $0.location == end && $0 != selection } ?? false
        if let oldCount = before.count {
            guard oldCount >= 0, selection.location + selection.length <= oldCount else { return nil }
        }
        if let newCount = after.count {
            guard newCount >= 0, end <= newCount else { return nil }
        }
        var countChanged = false
        if let oldCount = before.count, let newCount = after.count {
            let expectedDelta = observedLength - selection.length
            guard newCount - oldCount == expectedDelta else { return nil }
            countChanged = expectedDelta != 0
        }
        guard cursorMoved || countChanged else { return nil }
        return NSRange(location: selection.location, length: observedLength)
    }

    static func readText(in range: NSRange, from element: AXUIElement?) -> String? {
        guard let element, range.location >= 0, range.length > 0,
              range.location <= Int.max - range.length else { return nil }
        var cfRange = CFRange(location: range.location, length: range.length)
        guard let value = AXValueCreate(.cfRange, &cfRange) else { return nil }
        var result: CFTypeRef?
        guard AXUIElementCopyParameterizedAttributeValue(
            element, kAXStringForRangeParameterizedAttribute as CFString, value, &result
        ) == .success else { return nil }
        return result as? String
    }

    static func verificationTimeout(for text: String, before: FieldSnapshot) -> TimeInterval {
        guard before.value != nil || before.selection != nil else { return 3 }
        let extra = max(0, Double(text.utf16.count - min(text.utf16.count, 1_000)) / 1_000)
        return min(8, 3 + extra)
    }

    /// Selection-free editors can prove a pure insertion, not an arbitrary edit.
    /// Bound the candidate range with unchanged UTF-16 prefixes and suffixes.
    private static func matchesInsertion(old: String, new: String, text: String) -> Bool {
        let a = Array(old.utf16)
        let b = Array(new.utf16)
        let length = text.utf16.count
        guard b.count == a.count + length else { return false }
        let prefix = zip(a, b).prefix { $0 == $1 }.count
        let suffix = zip(a.reversed(), b.reversed()).prefix { $0 == $1 }.count
        let lower = a.count - suffix
        guard lower <= prefix else { return false }
        let value = new as NSString
        let match = value.range(of: text, options: .literal,
                                range: NSRange(location: lower, length: prefix - lower + length))
        return match.location != NSNotFound && value.replacingCharacters(in: match, with: "") == old
    }

    /// Metni kullanıcının elle yapıştırabileceği şekilde panoya koyar
    /// (geçici etiket olmadan; pano yöneticileri de görür).
    private func leaveOnClipboard(_ text: String) -> Bool {
        if let fallbackClipboardOverride { return fallbackClipboardOverride(text) }
        return setClipboard(text)
    }

    /// Dikte edilen metni hedef alana yapıştırır.
    ///
    /// 1. Kayıt başındaki uygulama, pencere ve alanın odağı doğrulanır.
    /// 2. Seçilmişse başlangıçtaki alan yeniden odaklanır ve tekrar doğrulanır.
    ///    Hedefe dönülemiyorsa metin panoya bırakılır.
    /// 3. Cmd+V yalnızca hedef sürece gönderilir ve alan içeriği izlenir.
    /// 4. Teslimat doğrulanmadıysa otomatik gönderim ve pano geri yüklemesi yapılmaz.
    ///
    /// Dönüş değeri yalnızca işlemin başlatılıp başlatılmadığıdır; kesin
    /// sonuç `completion` ile ana thread'de gelir. `onAttempted`, aktarım
    /// isteği gönderildiğinde çağrılır ve başarılı teslim anlamına gelmez.
    @discardableResult
    public func paste(
        text: String,
        targetContext: TargetContext? = nil,
        restoreClipboard: Bool = false,
        pasteDelayMs: Int = 20,
        autoSubmit: Bool = false,
        autoSubmitKey: String = "return",
        typeDirectly: Bool = false,
        restoreOriginalTarget: Bool = false,
        cancellation: InjectionCancellation? = nil,
        observer: DeliveryObserver? = nil,
        completion: ((InjectionOutcome) -> Void)? = nil
    ) -> Bool {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }

        let generation = currentGeneration()
        let attempted: () -> Void = {
            guard let observer else { return }
            DispatchQueue.main.async(execute: observer.onAttempted)
        }
        let finish: (InjectionOutcome) -> Void = { outcome in
            DispatchQueue.main.async { completion?(outcome) }
        }
        queue.async { [self] in
            let cancelled = { self.currentGeneration() != generation || cancellation?.isCancelled == true }
            guard !cancelled() else { return finish(.cancelled) }
            performPaste(text: text, targetContext: targetContext,
                         restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
                         autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
                         typeDirectly: typeDirectly, restoreOriginalTarget: restoreOriginalTarget,
                         isCancelled: cancelled, onAttempted: attempted, finish: finish)
        }
        return true
    }

    private func performPaste(
        text: String, targetContext: TargetContext?, restoreClipboard: Bool,
        pasteDelayMs: Int, autoSubmit: Bool, autoSubmitKey: String, typeDirectly: Bool,
        restoreOriginalTarget: Bool, isCancelled: @escaping () -> Bool,
        onAttempted: @escaping () -> Void, finish: @escaping (InjectionOutcome) -> Void
    ) {
        guard !isCancelled() else { return finish(.cancelled) }
        if case let .changed(reason) = checkTarget(targetContext) {
            var restored = false
            if restoreOriginalTarget, let target = targetContext, !isCancelled() {
                restored = restoreTargetOverride?(target)
                    ?? TargetInputManager.shared.restoreTargetFocus(to: target, isCancelled: isCancelled)
                if restored, !isCancelled() { restored = checkTarget(target) == .same }
            }
            guard !isCancelled() else { return finish(.cancelled) }
            if !restored {
                print("[TextInjector] 🛑 Hedef değişti (\(reason)); yapıştırılmadı, metin panoya bırakıldı.")
                let copied = Self.onMain { !isCancelled() && leaveOnClipboard(text) }
                finish(isCancelled() ? .cancelled : copied ? .targetChanged(reason: reason) : .failed(reason: "Metin panoya yazılamadı"))
                return
            }
        }

        // Güvenli Giriş Teşhisi (Secure Event Input Check)
        if SecureInputDiagnostics.isSecureInputActive() {
            print("[TextInjector] ⚠️ Güvenli Giriş (Secure Event Input) devrede. Sistem parola alanında olabilir, sentetik Cmd+V kısıtlanabilir.")
        }

        // İsteğe bağlı seçili metin aktarımı → desteklenmiyorsa pano + Cmd+V.
        guard typeDirectly else {
            return pasteViaClipboard(
                text: text, target: targetContext, restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
                autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
                isCancelled: isCancelled, onAttempted: onAttempted, finish: finish
            )
        }
        insertWithoutInputMethod(
            text: text, target: targetContext, typeDirectly: typeDirectly,
            restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
            autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
            isCancelled: isCancelled, onAttempted: onAttempted, finish: finish
        )
    }

    // MARK: - Panosuz yazma yöntemleri

    /// Desteklenen alanlarda yalnızca seçili metni değiştirir. Bir yazma
    /// girişiminden sonra çift teslimatı önlemek için başka yöntem denenmez.
    private func insertWithoutInputMethod(
        text: String,
        target: TargetContext?,
        typeDirectly: Bool,
        restoreClipboard: Bool,
        pasteDelayMs: Int,
        autoSubmit: Bool,
        autoSubmitKey: String,
        isCancelled: @escaping () -> Bool,
        onAttempted: @escaping () -> Void,
        finish: @escaping (InjectionOutcome) -> Void
    ) {
        guard !isCancelled() else { return finish(.cancelled) }
        if typeDirectly, let target {
            let field = target.element
            var environment: SelectedTextTransaction.Environment
            if let selectedTextEnvironmentOverride {
                environment = selectedTextEnvironmentOverride(target)
                let environmentCancelled = environment.isCancelled
                environment.isCancelled = { isCancelled() || environmentCancelled() }
            } else {
                AXUIElementSetMessagingTimeout(field, 0.25)
                environment = SelectedTextTransaction.Environment(
                    supportsSelectedText: {
                        var settable: DarwinBoolean = false
                        return AXUIElementIsAttributeSettable(field, kAXSelectedTextAttribute as CFString, &settable) == .success
                            && settable.boolValue
                    },
                    targetChangedReason: { [self] in
                        if case let .changed(reason) = checkTarget(target) { return reason }
                        return nil
                    },
                    snapshot: { Self.snapshot(of: field) },
                    writeSelectedText: { value in
                        AXUIElementSetAttributeValue(field, kAXSelectedTextAttribute as CFString, value as CFString) == .success
                    },
                    autoSubmit: { [self] in triggerAutoSubmit(key: autoSubmitKey, targetPID: target.pid) },
                    isCancelled: isCancelled,
                    readRange: { Self.readText(in: $0, from: field) }
                )
            }
            switch SelectedTextTransaction.run(text: text, autoSubmit: autoSubmit, environment: environment,
                                               onAttempted: onAttempted) {
            case .unsupported:
                break
            case let .finished(.targetChanged(reason)):
                let copied = Self.onMain { !isCancelled() && leaveOnClipboard(text) }
                return finish(isCancelled() ? .cancelled : copied ? .targetChanged(reason: reason) : .failed(reason: "Metin panoya yazılamadı"))
            case let .finished(outcome):
                return finish(outcome)
            }
        }

        pasteViaClipboard(
            text: text, target: target, restoreClipboard: restoreClipboard, pasteDelayMs: pasteDelayMs,
            autoSubmit: autoSubmit, autoSubmitKey: autoSubmitKey,
            isCancelled: isCancelled, onAttempted: onAttempted, finish: finish
        )
    }

    /// Eski karakter bölümleme kuralları yalnızca uyumluluk testlerinde kullanılır.
    /// Etkin teslimat artık metni sentetik karakter olaylarına bölmez.
    static func canTypeAsCharacters(_ text: String) -> Bool {
        !text.isEmpty && text.count <= 4000 && text.rangeOfCharacter(from: .newlines) == nil && !text.contains("\t")
    }

    static func sendCharacterChunks(_ text: String, isCancelled: () -> Bool,
                                    send: ([UniChar]) -> Bool) -> Bool {
        var chunk: [UniChar] = []
        func flush() -> Bool {
            guard !isCancelled() else { return false }
            guard !chunk.isEmpty else { return true }
            guard send(chunk) else { return false }
            chunk.removeAll(keepingCapacity: true)
            return true
        }
        // Karakter sınırında böl: emoji ve birleşik harfler parçalanmaz.
        for character in text {
            guard !isCancelled() else { return false }
            let units = Array(String(character).utf16)
            if chunk.count + units.count > 20, !flush() { return false }
            chunk.append(contentsOf: units)
        }
        return flush()
    }

    private func pasteViaClipboard(
        text: String,
        target: TargetContext?,
        restoreClipboard: Bool,
        pasteDelayMs: Int,
        autoSubmit: Bool,
        autoSubmitKey: String,
        isCancelled: @escaping () -> Bool,
        onAttempted: @escaping () -> Void,
        finish: @escaping (InjectionOutcome) -> Void
    ) {
        let environment = clipboardEnvironment(text: text, target: target,
                                               restoreClipboard: restoreClipboard,
                                               autoSubmitKey: autoSubmitKey, isCancelled: isCancelled)
        let outcome = ClipboardPasteTransaction.run(
            text: text, pasteDelay: Double(max(0, pasteDelayMs)) / 1000,
            restoreClipboard: restoreClipboard, autoSubmit: autoSubmit, environment: environment,
            onAttempted: onAttempted
        )
        print("[TextInjector] Teslim sonucu: \(outcome), uzunluk: \(text.utf16.count)")
        finish(outcome)
    }

    private func clipboardEnvironment(
        text: String, target: TargetContext?, restoreClipboard: Bool,
        autoSubmitKey: String, isCancelled: @escaping () -> Bool
    ) -> ClipboardPasteTransaction.Environment {
        if let clipboardEnvironmentOverride {
            var environment = clipboardEnvironmentOverride(text)
            let environmentCancelled = environment.isCancelled
            environment.isCancelled = { isCancelled() || environmentCancelled() }
            return environment
        }
        var previous: [NSPasteboardItem] = []
        var ownedChangeCount: Int?
        var preparationFailure = "Metin panoya yazılamadı"
        if let field = target?.element { AXUIElementSetMessagingTimeout(field, 0.25) }
        return ClipboardPasteTransaction.Environment(
            prepare: { [self] in
                Self.onMain {
                    guard !isCancelled() else { return false }
                    let pb = NSPasteboard.general
                    let initialChangeCount = pb.changeCount
                    if restoreClipboard {
                        guard let snapshot = captureCompleteClipboardSnapshot(from: pb) else {
                            preparationFailure = "Pano yedeklenemedi; pano değiştirilmedi"
                            return false
                        }
                        previous = snapshot
                        // Another process may copy while the snapshot is being read.
                        guard pb.changeCount == initialChangeCount, !isCancelled() else { return false }
                    }
                    guard let item = Self.transientClipboardItem(text: text) else { return false }
                    guard !isCancelled(), pb.changeCount == initialChangeCount else { return false }
                    let clearedChangeCount = pb.clearContents()
                    guard pb.writeObjects([item]) else {
                        if restoreClipboard, pb.changeCount == clearedChangeCount,
                           !restoreClipboardSnapshot(previous) {
                            preparationFailure = "Pano geri yüklenemedi; önceki içeriği kontrol edin"
                        }
                        return false
                    }
                    ownedChangeCount = pb.changeCount
                    return true
                }
            },
            preparationFailureReason: { preparationFailure },
            ownsClipboard: { Self.onMain { NSPasteboard.general.changeCount == ownedChangeCount } },
            targetChangedReason: { [self] in
                if case let .changed(reason) = checkTarget(target) { return reason }
                return nil
            },
            snapshot: { Self.snapshot(of: target?.element) },
            sendPaste: { [self] in
                guard let pid = target?.pid, !isCancelled() else { return false }
                guard let vKeyCode = Self.onMain({ Self.resolvedKeyCodeForCharacter("v") }) else { return false }
                guard !isCancelled(), checkTarget(target) == .same,
                      Self.onMain({ NSPasteboard.general.changeCount == ownedChangeCount }),
                      !isCancelled() else { return false }
                return simulateCmdV(vKeyCode: vKeyCode, targetPID: pid)
            },
            restore: { [self] in
                Self.onMain {
                    // Recheck inside the same main-thread operation as restoration.
                    guard !isCancelled(), NSPasteboard.general.changeCount == ownedChangeCount else { return }
                    _ = restoreClipboardSnapshot(previous)
                }
            },
            autoSubmit: { [self] in
                guard !isCancelled(), let pid = target?.pid else { return }
                triggerAutoSubmit(key: autoSubmitKey, targetPID: pid)
            },
            rollbackBeforeSending: { [self] in
                Self.onMain {
                    guard NSPasteboard.general.changeCount == ownedChangeCount else { return }
                    _ = restoreClipboardSnapshot(previous)
                }
            },
            isCancelled: isCancelled,
            readRange: { Self.readText(in: $0, from: target?.element) }
        )
    }

    /// inject metodu
    @discardableResult
    public func inject(
        text: String,
        targetContext: TargetContext? = nil,
        pasteDelayMs: Int = 20,
        cancellation: InjectionCancellation? = nil,
        observer: DeliveryObserver? = nil,
        completion: ((InjectionOutcome) -> Void)? = nil
    ) -> Bool {
        let config = configProvider()
        return paste(
            text: text,
            targetContext: targetContext,
            restoreClipboard: config.restore_clipboard,
            pasteDelayMs: pasteDelayMs,
            autoSubmit: config.enable_auto_submit,
            autoSubmitKey: config.auto_submit_key,
            typeDirectly: config.type_text_directly,
            restoreOriginalTarget: config.restore_target_focus,
            cancellation: cancellation,
            observer: observer,
            completion: completion
        )
    }
}


